#[cfg(test)]mod repeated_checkpoint_tests{use super::*;#[test]fn checkpoint_metadata_is_not_recursively_replayed_as_user_discussion(){let history=vec![ChatMessage{role:ChatRole::User,content:json!({"primsHarnessContext":{"originalUserRequest":"goal"}}).to_string()},ChatMessage{role:ChatRole::User,content:"goal".into()},ChatMessage{role:ChatRole::User,content:format!("{}old checkpoint",SUMMARY_PREFIX.trim())}];assert_eq!(compaction_user_messages(&history,"goal"),vec!["goal"]);}}
